    val specimens: List<Specimen> = listOf(
        Specimen(id = "acanthite", name = "Acanthite", rockClass = RockClass.MINERAL, category = "Sulfide — Silver ore", tagline = "Dark gray silver sulfide — one of the most important silver ores on Earth.", emoji = "\u2B1B", colorHex = 0xFF1A1A2A, description = "Acanthite is a silver sulfide mineral and one of the most important silver ores. It forms dark gray to black metallic masses and may develop wire-like or dendritic (tree-like) crystal forms in open cavities. Below 173°C, it is the stable form of silver sulfide.", formation = "Forms in the oxidized zones of silver deposits and in hydrothermal veins. Often found as a secondary mineral where primary silver minerals have been altered by groundwater.", hardness = "2–2.5", luster = "Metallic", streak = "Black", crystalSystem = "Monoclinic", chemicalFormula = "Ag₂S", commonColors = listOf("Dark gray", "Iron black", "Lead gray"), whereFound = listOf("Mexico", "Peru", "Nevada, USA", "Germany"), funFacts = listOf("Above 173°C, it transforms into argentite — the same mineral with a different structure.", "Wire silver specimens often have a thin coating of acanthite.", "It tarnishes black quickly on exposure to light and air."), uses = "Silver ore, collector specimens, historical source of silver.", rarity = "Uncommon"),
        Specimen(id = "calcite-cobalt", name = "Calcite, Cobaltoan", rockClass = RockClass.CRYSTAL, category = "Carbonate — Calcite variety", tagline = "Hot pink drusy calcite from the copper-cobalt mines of the Congo.", emoji = "\uD83C\uDF38", colorHex = 0xFFE85090, description = "Cobalt calcite (cobaltoan calcite) is a stunning hot pink to magenta variety of calcite colored by trace cobalt. The color is so vivid it almost looks artificial — drusy crusts of tiny sparkling pink crystals carpeting dark gray dolomite matrix. Most fine specimens come from the Congo.", formation = "The pink color comes from cobalt ions (Co²⁺) substituting for calcium in the calcite crystal lattice. The drusy form grows in open cavities in cobalt-rich copper deposits.", hardness = "3 (Mohs)", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "(Ca,Co)CO₃", commonColors = listOf("Hot pink", "Magenta", "Pale pink"), whereFound = listOf("Katanga Province, Democratic Republic of Congo", "Morocco", "Italy"), funFacts = listOf("The pink color is so vivid it's sometimes called 'bubblegum calcite.'", "The finest specimens come from the Mashamba West mine in the Congo.", "It's one of the few minerals that's colored pink by cobalt."), uses = "Collector specimens, decorative display pieces, rarely cabochons.", rarity = "Uncommon"),
        Specimen(id = "calcite-dogtooth", name = "Calcite, Dogtooth Spar", rockClass = RockClass.CRYSTAL, category = "Carbonate — Calcite variety", tagline = "Sharp golden crystals pointing upward like canine teeth in a limestone cave.", emoji = "\uD83D\uDC3A", colorHex = 0xFFD4A840, description = "Dogtooth spar is calcite that forms sharp, pointed scalenohedral crystals resembling canine teeth. The golden-amber color comes from iron oxide inclusions. These dramatic crystal clusters form in limestone caves and vugs worldwide.", formation = "Crystallizes from calcium-rich groundwater in limestone caves and vugs. The scalenohedral crystal form is the result of rapid growth with uneven faces — creating the sharp, tooth-like points.", hardness = "3 (Mohs)", luster = "Vitreous to sub-vitreous", streak = "White", crystalSystem = "Trigonal (scalenohedral)", chemicalFormula = "CaCO₃", commonColors = listOf("Golden amber", "Honey brown", "White", "Colorless"), whereFound = listOf("Missouri, USA", "England", "Mexico", "China"), funFacts = listOf("The tooth-like shape forms from rapid, uneven crystal growth.", "Some dogtooth calcite crystals fluoresce bright pink-orange under UV.", "The largest dogtooth crystals can exceed 12 inches in length."), uses = "Collector specimens, cave tourism, decorative specimens.", rarity = "Common"),
        Specimen(id = "calcite-iceland-spar", name = "Calcite, Iceland Spar", rockClass = RockClass.CRYSTAL, category = "Carbonate — Calcite variety", tagline = "The crystal that splits light in two — nature's original polarizer.", emoji = "\uD83D\uDD2E", colorHex = 0xFFF0F4F8, description = "Iceland spar is an exceptionally clear, colorless variety of calcite famous for its strong double refraction (birefringence). When you place it over text, you see two images — a property that made it essential for early optical instruments and polarizing microscopes. Rarity: Uncommon (optical grade).", formation = "Forms in large, clear rhombohedral crystals from hydrothermal solutions in basalt cavities. The famous Iceland locality produced crystals up to several feet across.", hardness = "3 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "CaCO₃", commonColors = listOf("Colorless", "Water-clear"), whereFound = listOf("Helgustadir, Iceland", "New Mexico, USA", "Mexico", "China"), funFacts = listOf("The double refraction is so strong you can read two lines of text through it.", "Iceland spar was crucial for 17th-century discoveries about the nature of light.", "The Vikings may have used it as a 'sunstone' for navigation on cloudy days."), uses = "Optics, polarizing prisms, educational specimens, collector pieces.", rarity = "Uncommon (optical grade)"),
        Specimen(id = "calcite-mangano", name = "Calcite, Mangano", rockClass = RockClass.CRYSTAL, category = "Carbonate — Calcite variety", tagline = "Soft pastel pink botryoidal calcite — nature's most gentle pink stone.", emoji = "\uD83C\uDF38", colorHex = 0xFFF0C0C8, description = "Mangano calcite (manganocalcite) is a pastel pink variety of calcite colored by trace manganese. It usually forms in botryoidal (grape-like) masses with a soft, waxy-pearly luster. The delicate pink color has made it popular among collectors and for metaphysical use.", formation = "The soft pink color is caused by manganese (Mn²⁺) substituting for calcium. UV light often produces a strong orange-pink fluorescence — a classic test for manganese in calcite.", hardness = "3 (Mohs)", luster = "Waxy to pearly", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "(Ca,Mn)CO₃", commonColors = listOf("Pastel pink", "Pale rose", "Peach pink"), whereFound = listOf("Peru", "Mexico", "Bulgaria", "South Africa"), funFacts = listOf("It fluoresces brilliant orange-pink under UV light.", "The manganese gives it a softer, more gentle pink than cobalt calcite.", "Some specimens also contain tiny pyrite crystals for extra sparkle."), uses = "Collector specimens, metaphysical crystal healing, carvings.", rarity = "Uncommon"),
        Specimen(id = "calcite-nailhead", name = "Calcite, Nailhead Spar", rockClass = RockClass.CRYSTAL, category = "Carbonate — Calcite variety", tagline = "Flat-topped hexagonal crystals with beveled edges — like a box of nails.", emoji = "\uD83D\uDD28", colorHex = 0xFFF0E8D0, description = "Nailhead spar is calcite with distinctive flat-topped hexagonal crystals that have beveled edges — resembling the heads of old-fashioned nails. The pale yellow to creamy white crystals form in compact drusy clusters on limestone.", formation = "Forms when calcite crystallizes slowly in limestone cavities, developing the characteristic hexagonal prism shape with a flat pinacoid termination. The beveled edges are the result of truncation by rhombohedral faces.", hardness = "3 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "CaCO₃", commonColors = listOf("Pale yellow", "Cream white", "Pale gray"), whereFound = listOf("Derbyshire, England", "Illinois, USA", "Tennessee, USA"), funFacts = listOf("Named for the resemblance to hand-forged nail heads.", "It's actually calcite with a different combination of crystal faces.", "The beveled edges are secondary rhombohedral faces trimming the crystal."), uses = "Collector specimens, educational display pieces.", rarity = "Common"),
        Specimen(id = "corundum-green-sapphire", name = "Corundum, Green Sapphire", rockClass = RockClass.CRYSTAL, category = "Oxide — Corundum variety", tagline = "Muted olive-green corundum — the earthy, understated sapphire.", emoji = "\uD83D\uDFE2", colorHex = 0xFF6A8A4A, description = "Green sapphire ranges from pale mint to deep olive-green. Unlike emerald, green sapphire gets its color from iron rather than chromium — creating a more muted, earthy green. It's an excellent choice for those who love green gemstones but want sapphire's legendary hardness.", formation = "Iron (Fe²⁺/Fe³⁺) in the crystal lattice creates the green color. The amount and oxidation state of iron determine the depth of green.", hardness = "9 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Al₂O₃ (with Fe²⁺/Fe³⁺)", commonColors = listOf("Olive green", "Mint green", "Forest green", "Yellowish-green"), whereFound = listOf("Thailand", "Australia", "Sri Lanka", "Montana, USA"), funFacts = listOf("Green sapphire is much harder than emerald (9 vs 7.5–8).", "Australian green sapphires often have a distinct teal tint.", "Green sapphires from Montana's Rock Creek deposit are particularly prized."), uses = "Engagement rings, daily-wear jewelry requiring durability.", rarity = "Uncommon"),
        Specimen(id = "corundum-padparadscha", name = "Corundum, Padparadscha Sapphire", rockClass = RockClass.CRYSTAL, category = "Oxide — Corundum variety", tagline = "The rarest sapphire color — a delicate pinkish-orange like a tropical lotus flower.", emoji = "\uD83C\uDF38", colorHex = 0xFFE8A090, description = "Padparadscha is the rarest and most valuable sapphire color — a delicate blend of pink and orange reminiscent of a lotus blossom at dawn. The name comes from the Sinhalese word for 'lotus flower.' True padparadscha must show both pink and orange simultaneously.", formation = "The unique color comes from a precise combination of chromium (pink) and iron with a specific oxidation state (orange). Too much of either element ruins the padparadscha effect.", hardness = "9 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Al₂O₃ (with Cr³⁺ and Fe³⁺ color centers)", commonColors = listOf("Pinkish-orange", "Salmon", "Lotus blossom"), whereFound = listOf("Sri Lanka", "Madagascar", "Tanzania"), funFacts = listOf("The name means 'lotus flower' in Sinhalese.", "Experts still debate the exact color range of a true padparadscha.", "A fine padparadscha can be worth more than an equivalent blue sapphire."), uses = "High-end jewelry, collector investment stones.", rarity = "Very rare"),
        Specimen(id = "corundum-pink-sapphire", name = "Corundum, Pink Sapphire", rockClass = RockClass.CRYSTAL, category = "Oxide — Corundum variety", tagline = "Vivid pink corundum — the romantic sister of ruby.", emoji = "\uD83C\uDF38", colorHex = 0xFFE890A0, description = "Pink sapphire is corundum colored by chromium, just like ruby — but at a lower concentration that creates a pink rather than red color. The boundary between pink sapphire and ruby is famously debated, but all are treasured for their brilliance and hardness.", formation = "Chromium atoms replace aluminum in the crystal lattice, creating pink coloration through the same mechanism as ruby. The chromium concentration is simply lower — below the threshold where it's called ruby.", hardness = "9 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Al₂O₃ (with low Cr³⁺)", commonColors = listOf("Vivid pink", "Pastel pink", "Hot pink", "Bubblegum pink"), whereFound = listOf("Sri Lanka", "Madagascar", "Myanmar", "Tanzania"), funFacts = listOf("There's no scientific difference between pink sapphire and ruby — just marketing.", "Sri Lanka is the historical source of the world's finest pink sapphires.", "Princess Diana's famous engagement ring is centered with a blue sapphire."), uses = "Engagement rings, fine jewelry, high-end timepieces.", rarity = "Uncommon to rare"),
        Specimen(id = "corundum-purple-sapphire", name = "Corundum, Purple Sapphire", rockClass = RockClass.CRYSTAL, category = "Oxide — Corundum variety", tagline = "Violet to plum corundum — sapphire's regal purple side.", emoji = "\uD83D\uDFE3", colorHex = 0xFF7A5AAA, description = "Purple sapphire ranges from delicate lavender to deep plum-violet. The color comes from a unique combination of chromium and iron color centers that create the purple hue — distinct from the red of ruby or the pink of pink sapphire. Sri Lanka and Madagascar are the primary sources.", formation = "The purple color is caused by chromium (red) and iron (blue) color centers interacting in the crystal lattice. The balance between these elements determines the shade of purple.", hardness = "9 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Al₂O₃ (with Cr³⁺ and Fe²⁺/Fe³⁺)", commonColors = listOf("Violet-purple", "Lavender", "Plum", "Grape"), whereFound = listOf("Sri Lanka", "Madagascar", "Tanzania", "Kenya"), funFacts = listOf("Purple sapphire is sometimes called 'Oriental amethyst' in the trade.", "The finest purple sapphires have an electric violet glow.", "They combine the passion of red with the calm of blue."), uses = "Fine jewelry, collector gemstones, metaphysical/spiritual jewelry.", rarity = "Rare"),
        Specimen(id = "corundum-ruby-burma", name = "Corundum, Ruby (Burma)", rockClass = RockClass.CRYSTAL, category = "Oxide — Corundum variety", tagline = "The legendary pigeon-blood red ruby from Myanmar's Mogok Valley.", emoji = "\uD83D\uDC8E", colorHex = 0xFFCC0A2A, description = "Burmese rubies from the Mogok Valley are the most legendary and valuable rubies in the world. The finest exhibit 'pigeon's blood' red — a pure fluorescent crimson with a hint of blue. These red hexagonal crystals, often embedded in white marble, have been treasured for over a thousand years. Rarity: Very rare (fine quality).", formation = "Forms in marble-hosted deposits where aluminum-rich fluids encounter chromium-bearing marble. The chromium creates the red color and strong red fluorescence under UV light.", hardness = "9 (Mohs)", luster = "Vitreous to adamantine", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Al₂O₃ (with Cr³⁺)", commonColors = listOf("Pigeon's blood red", "Crimson", "Deep purplish-red"), whereFound = listOf("Mogok Valley, Myanmar", "Mong Hsu, Myanmar"), funFacts = listOf("Burmese rubies glow an intense red under UV light from their high chromium.", "A single Mogok ruby can fetch more per carat than any diamond.", "The Mogok mines have produced rubies for over 1,000 years."), uses = "High-end jewelry, investment-grade gemstones, watchmaking.", rarity = "Very rare (fine quality)"),
        Specimen(id = "corundum-ruby-mozambique", name = "Corundum, Ruby (Mozambique)", rockClass = RockClass.CRYSTAL, category = "Oxide — Corundum variety", tagline = "Deep purplish-red ruby crystals from East Africa's prolific gem fields.", emoji = "\uD83D\uDC8E", colorHex = 0xFF9A1A3A, description = "Mozambique rubies from the Montepuez deposit have reshaped the ruby market since their discovery in 2009. These purplish-red crystals form in dark amphibole matrix and are now among the world's most important ruby sources — rivaling Burma in production volume.", formation = "Forms in amphibole-rich metamorphic rocks where chromium-bearing fluids react with aluminum-rich minerals. The dark amphibole matrix is characteristic of these deposits.", hardness = "9 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Al₂O₃ (with Cr³⁺, Fe³⁺)", commonColors = listOf("Purplish-red", "Deep crimson", "Blood red with purple undertone"), whereFound = listOf("Montepuez, Cabo Delgado, Mozambique", "Niassa Province, Mozambique"), funFacts = listOf("The Montepuez deposit was only discovered in 2009 but is now world-class.", "Mozambique rubies often have a more purplish hue than Burmese rubies.", "They tend to be cleaner (fewer inclusions) than Burmese material."), uses = "High-end jewelry, engagement rings, investment gemstones.", rarity = "Rare"),
        Specimen(id = "corundum-teal-sapphire", name = "Corundum, Teal Sapphire", rockClass = RockClass.CRYSTAL, category = "Oxide — Corundum variety", tagline = "Blue-green teal corundum — like tropical ocean water in a crystal.", emoji = "\uD83C\uDF0A", colorHex = 0xFF3A7A8A, description = "Teal sapphire displays a captivating blue-green color — part blue sapphire, part green sapphire — reminiscent of tropical ocean waters. These unique stones have surged in popularity for engagement rings since the 2010s, offering a distinctive alternative to traditional blue sapphires.", formation = "A combination of iron and titanium creates the blue-green teal color. The specific ratio of these elements determines whether the stone leans more blue or more green.", hardness = "9 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Al₂O₃ (with Fe²⁺/Fe³⁺, Ti⁴⁺)", commonColors = listOf("Teal blue-green", "Ocean teal", "Pale aqua-teal"), whereFound = listOf("Montana, USA", "Australia", "Sri Lanka", "Madagascar"), funFacts = listOf("Montana teal sapphires are among the most sought-after in the world.", "The color often looks different in daylight vs. incandescent light.", "No two teal sapphires look exactly alike — each is unique."), uses = "Engagement rings, fine jewelry, ethical/alternative gemstones.", rarity = "Rare to uncommon"),
        Specimen(id = "corundum-yellow-sapphire", name = "Corundum, Yellow Sapphire", rockClass = RockClass.CRYSTAL, category = "Oxide — Corundum variety", tagline = "Golden-yellow corundum crystals — the sunny sapphire of wisdom.", emoji = "\u2600\uFE0F", colorHex = 0xFFE8B830, description = "Yellow sapphire ranges from pale lemon to rich golden-yellow. In Vedic astrology, it is the most powerful of the nine planetary gemstones — associated with Jupiter and the pursuit of wisdom and prosperity. The finest yellow sapphires come from Sri Lanka.", formation = "Yellow coloration comes from trace iron (Fe³⁺) in the crystal lattice. Heat treatment can enhance or create yellow color by altering the iron oxidation state.", hardness = "9 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Al₂O₃ (with Fe³⁺)", commonColors = listOf("Golden yellow", "Canary yellow", "Pale lemon", "Honey amber"), whereFound = listOf("Sri Lanka", "Thailand", "Madagascar", "Tanzania"), funFacts = listOf("In Vedic astrology, it's the primary gem for the planet Jupiter.", "Sri Lanka's yellow sapphires have been prized for over 2,000 years.", "Most commercial yellow sapphires are heat-treated to improve color."), uses = "Astrological jewelry, engagement rings, fine jewelry.", rarity = "Uncommon"),
        Specimen(id = "feldspar-andesine", name = "Andesine", rockClass = RockClass.MINERAL, category = "Silicate — Feldspar group", tagline = "Rare reddish-orange plagioclase feldspar with a vitreous glow.", emoji = "\uD83D\uDD36", colorHex = 0xFFD08050, description = "Andesine is a plagioclase feldspar in the middle of the albite-anorthite series. The rare transparent reddish-orange gem variety has gained attention in recent decades, though the origins of some material have been controversial. It was named after the Andes Mountains. Rarity: Rare (gem quality).", formation = "Forms in intermediate igneous rocks like andesite and diorite. The red-orange gem variety gets its color from trace copper — a rare substitution in feldspar.", hardness = "6–6.5", luster = "Vitreous", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "(Na,Ca)(Al,Si)₄O₈ (30–50% anorthite)", commonColors = listOf("Reddish-orange", "Green-yellow", "White", "Gray"), whereFound = listOf("Andes Mountains, South America", "Tibet", "Congo", "Oregon, USA"), funFacts = listOf("Gem-quality red-orange andesine was once believed to be a new gemstone.", "The copper-colored variety is sometimes confused with sunstone.", "Named for the Andes Mountains where it was first identified."), uses = "Gemstone, collector specimens, rarely faceted for jewelry.", rarity = "Rare (gem quality)"),
        Specimen(id = "feldspar-anorthite", name = "Anorthite", rockClass = RockClass.MINERAL, category = "Silicate — Feldspar group", tagline = "The calcium end-member of plagioclase — pure white to gray with glassy cleavage.", emoji = "\u2B1C", colorHex = 0xFFE8E0D8, description = "Anorthite is the calcium end-member of the plagioclase feldspar series. It is the rarest of the named plagioclase varieties, found mainly in calcium-rich mafic and ultramafic rocks. Pure white to gray with a vitreous-to-pearly luster on cleavage faces.", formation = "Forms in calcium-rich mafic igneous rocks, particularly anorthosites and gabbros. It also occurs in contact metamorphic rocks and some meteorites.", hardness = "6–6.5", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "CaAl₂Si₂O₈", commonColors = listOf("White", "Pale gray", "Colorless", "Pinkish-gray"), whereFound = listOf("Italy (Mt. Vesuvius)", "Japan", "California, USA", "Moon (lunar anorthosite)"), funFacts = listOf("Much of the Moon's light-colored highlands are anorthite-rich anorthosite.", "It's the rarest of the named plagioclase feldspars.", "Found in some meteorites — evidence of early solar system differentiation."), uses = "Scientific research, ceramics, collector specimens, lunar geology reference.", rarity = "Uncommon"),
        Specimen(id = "feldspar-bytownite", name = "Bytownite", rockClass = RockClass.MINERAL, category = "Silicate — Feldspar group", tagline = "Golden-yellow plagioclase feldspar — the rare middle child of the series.", emoji = "\uD83D\uDFE1", colorHex = 0xFFD4A840, description = "Bytownite is a calcium-rich plagioclase feldspar in the middle of the series — between labradorite and anorthite. It is relatively rare and was named after the old name for Ottawa, Canada where it was first identified. Golden-yellow transparent crystals are the most sought-after.", formation = "Forms in calcium-rich mafic igneous rocks such as gabbro and anorthosite. Rare transparent crystals grow in pegmatitic pockets.", hardness = "6–6.5", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "(Ca,Na)(Al,Si)₄O₈ (70–90% anorthite)", commonColors = listOf("Pale yellow", "Golden brown", "Gray-white", "Colorless"), whereFound = listOf("Ottawa (Bytown), Canada", "Montana, USA", "Scotland", "South Africa"), funFacts = listOf("Bytownite is one of the rarest named plagioclase varieties.", "It was named after Bytown, the original name for Ottawa.", "Golden transparent bytownite can be faceted as a collector's gem."), uses = "Collector specimens, rarely faceted gemstones.", rarity = "Rare"),
        Specimen(id = "feldspar-larvikite", name = "Larvikite", rockClass = RockClass.IGNEOUS, category = "Igneous — Feldspar-rich syenite", tagline = "Dark syenite sparkling with blue-silver feldspar crystals — the national stone of Norway.", emoji = "\u2728", colorHex = 0xFF2A2A3A, description = "Larvikite is a dark gray to black igneous rock composed primarily of feldspar with distinctive blue-to-silver iridescent crystals scattered throughout. It is Norway's national stone and is quarried extensively for use as dimension stone and countertops.", formation = "Forms from slow-cooling magma deep in the Earth's crust. The iridescence comes from microscopic exsolution lamellae in the feldspar crystals that diffract light — the same phenomenon as labradorite but in a darker matrix.", hardness = "6–6.5", luster = "Iridescent on cleavage faces", streak = "White", crystalSystem = "Triclinic (feldspar crystals)", chemicalFormula = "Na(AlSi₃O₈)-Ca(Al₂Si₂O₈) (feldspar dominated)", commonColors = listOf("Dark gray with silver-blue flash", "Black with blue iridescence"), whereFound = listOf("Larvik, Norway", "Ontario, Canada", "British Columbia, Canada"), funFacts = listOf("It's Norway's official national stone.", "The blue flash is the same optical effect as labradorite — labradorescence.", "The United Nations building in New York is clad in larvikite."), uses = "Dimension stone, countertops, architectural cladding, ornamental stone.", rarity = "Common"),
        Specimen(id = "feldspar-oligoclase", name = "Feldspar, Oligoclase", rockClass = RockClass.MINERAL, category = "Silicate — Feldspar group", tagline = "A translucent white plagioclase feldspar with a subtle pearly shimmer.", emoji = "\u2B1C", colorHex = 0xFFF5F0E8, description = "Oligoclase is a plagioclase feldspar with a sodium-rich composition. It forms translucent white to pale gray crystalline masses with a distinctive pearly luster on cleavage faces. Sunstone is actually oligoclase with copper inclusions.", formation = "Crystallizes in granitic pegmatites and syenites during slow cooling of felsic magmas. The plagioclase series forms a continuous solid solution from albite to anorthite.", hardness = "6–6.5", luster = "Pearly to vitreous", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "(Na,Ca)(Al,Si)₄O₈", commonColors = listOf("White", "Pale gray", "Colorless", "Yellowish"), whereFound = listOf("Norway", "Sweden", "Ontario, Canada", "New York, USA"), funFacts = listOf("Sunstone is actually oligoclase with hematite or copper platelets.", "The name comes from Greek 'oligos' (little) and 'klasis' (fracture).", "It's the most common plagioclase in granitic rocks."), uses = "Ceramics, glassmaking, ornamental stone, sunstone gem variety.", rarity = "Common"),
        Specimen(id = "feldspar-peristerite", name = "Peristerite", rockClass = RockClass.MINERAL, category = "Silicate — Feldspar group", tagline = "Blue-white adularescence on gray-white feldspar — like moonlight on water.", emoji = "\uD83C\uDF19", colorHex = 0xFFB0B8D0, description = "Peristerite is a variety of albite-oligoclase feldspar displaying a beautiful blue-white schiller or adularescence. This optical effect — a soft, floating blue light that appears to hover just beneath the surface — is caused by microscopic exsolution lamellae scattering light.", formation = "The adularescence is caused by light scattering from very thin alternating lamellae of albite and oligoclase that formed during slow cooling. The lamellae act like a natural diffraction grating.", hardness = "6–6.5", luster = "Pearly with blue schiller", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "(Na,Ca)(Al,Si)₄O₈", commonColors = listOf("White with blue flash", "Gray-white with violet shimmer"), whereFound = listOf("Ontario, Canada", "Quebec, Canada", "Norway", "Madagascar"), funFacts = listOf("The schiller is best seen when the stone is wet or polished.", "Named from Greek 'peristera' meaning dove — for its dove-like iridescence.", "Some specimens rival moonstone for beauty."), uses = "Cabochons, jewelry, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "fluorite-cubic-green", name = "Fluorite, Cubic Green", rockClass = RockClass.CRYSTAL, category = "Halide — Fluorite variety", tagline = "Perfectly transparent green cubes — fluorite in its purest geometric form.", emoji = "\uD83D\uDFE2", colorHex = 0xFF4A9A6A, description = "Cubic green fluorite from China and England forms beautifully transparent cubes with glass-clear interiors and sharp, undamaged edges. The green color comes from trace amounts of rare earth elements or radiation exposure. The cubic crystal form is the classic expression of fluorite's crystal structure.", formation = "Crystallizes from hydrothermal fluids in limestone and sandstone cavities. Pure cubic form indicates slow, undisturbed growth in open space — allowing perfect crystal faces to develop.", hardness = "4 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Cubic", chemicalFormula = "CaF₂ (with Sm²⁺ or radiation)", commonColors = listOf("Transparent green", "Pale sea green", "Yellow-green"), whereFound = listOf("Hunan Province, China", "Weardale, England", "Spain"), funFacts = listOf("Fluorite is the mineral that gave its name to fluorescence.", "Perfect cubes cleave into smaller perfect cubes when broken.", "The green color often changes to purple under sunlight over time."), uses = "Collector specimens, fluorite was historically used for optics.", rarity = "Common"),
        Specimen(id = "fluorite-illinois", name = "Fluorite, Illinois", rockClass = RockClass.CRYSTAL, category = "Halide — Fluorite variety", tagline = "The world's finest fluorite — deep purple cubes from the Cave-in-Rock district.", emoji = "\uD83D\uDFE3", colorHex = 0xFF6A3AAA, description = "Illinois fluorite from the Cave-in-Rock district is world-famous for its deep purple cubic crystals with sharp, distinct color zoning. These Mississippi Valley-type deposits produced some of the finest fluorite specimens ever collected, often associated with galena, sphalerite, and calcite. Rarity: Uncommon (quality specimens).", formation = "Forms from warm saline brines moving through limestone, depositing fluorite in open cavities. The color zoning — purple edges fading to clear centers — is characteristic of these deposits.", hardness = "4 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Cubic", chemicalFormula = "CaF₂ (with trace rare earth elements)", commonColors = listOf("Deep purple", "Blue-purple with zoning", "Yellow centers with purple edges"), whereFound = listOf("Cave-in-Rock, Illinois, USA", "Hardin County, Illinois", "Kentucky, USA"), funFacts = listOf("Illinois fluorite is the state mineral — but the mines closed in the 1990s.", "The color zoning is a hallmark of authentic Illinois fluorite.", "Some crystals show complete color change under different lighting."), uses = "Collector specimens, fluorite was historically used for steel flux.", rarity = "Uncommon (quality specimens)"),
        Specimen(id = "fluorite-pink", name = "Fluorite, Pink", rockClass = RockClass.CRYSTAL, category = "Halide — Fluorite variety", tagline = "Rare pink octahedral fluorite from the Swiss and French Alps.", emoji = "\uD83C\uDF38", colorHex = 0xFFE8A0B8, description = "Pink fluorite is one of the rarest fluorite colors, typically found as pale pink octahedral crystal clusters on gray gneiss or granite matrix from the Alpine regions of Europe. The color is caused by trace amounts of rare earth elements or radiation-induced color centers.", formation = "Forms in Alpine-type clefts where hot hydrothermal fluids deposit fluorite in open fissures within metamorphic rocks. The pink color is rare worldwide and is typically found in small, isolated pockets.", hardness = "4 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Cubic", chemicalFormula = "CaF₂ (with Y, Ce, or radiation centers)", commonColors = listOf("Pale pink", "Rose pink", "Pink with gray zoning"), whereFound = listOf("Swiss Alps", "French Alps", "Peru", "Pakistan"), funFacts = listOf("Pink is the rarest natural fluorite color.", "Swiss Alpine pink fluorite is among the most valuable fluorite worldwide.", "Some pink fluorites are colored by rare earth elements, others by radiation."), uses = "Premium collector specimens, rarely faceted for collectors.", rarity = "Rare"),
        Specimen(id = "jade-omphacite", name = "Jade, Omphacite", rockClass = RockClass.MINERAL, category = "Silicate — Pyroxene group", tagline = "The other true jade — bright green granular pyroxene from Myanmar.", emoji = "\uD83D\uDFE2", colorHex = 0xFF4A8A3A, description = "Omphacite jade is a bright green granular aggregate of omphacite pyroxene. Along with jadeite, it is one of the minerals that compose true jade. It is found in the same deposits as jadeite in Myanmar and can be indistinguishable from jadeite without sophisticated testing.", formation = "Forms under high-pressure, low-temperature conditions in subduction zone metamorphic rocks. The bright green color comes from chromium and iron substituting in the crystal structure.", hardness = "5.5–6", luster = "Vitreous to granular", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "(Ca,Na)(Mg,Fe,Al)Si₂O₆", commonColors = listOf("Bright green", "Olive green", "Dark green"), whereFound = listOf("Myanmar", "Guatemala", "Japan", "California, USA"), funFacts = listOf("Many 'jadeite' specimens are actually omphacite jade.", "It's chemically intermediate between jadeite and diopside.", "The name means 'unripe grape' in Greek — referencing its green color."), uses = "Jade carvings, jewelry, ornamental objects.", rarity = "Uncommon"),
        Specimen(id = "orpiment", name = "Orpiment", rockClass = RockClass.MINERAL, category = "Sulfide — Arsenic mineral", tagline = "Brilliant golden-orange arsenic sulfide — beautiful but deadly.", emoji = "\uD83D\uDD36", colorHex = 0xFFE8A030, description = "Orpiment is a strikingly beautiful arsenic sulfide mineral with a brilliant golden-orange to lemon-yellow color and a resinous luster. It was used as a pigment in ancient times — but it is highly toxic, containing up to 61% arsenic. Handle with care and never ingest.", formation = "Forms in low-temperature hydrothermal veins and hot spring deposits, often associated with realgar, stibnite, and cinnabar. Can also form as a volcanic sublimate.", hardness = "1.5–2", luster = "Resinous to pearly", streak = "Pale yellow", crystalSystem = "Monoclinic", chemicalFormula = "As₂S₃", commonColors = listOf("Golden-orange", "Lemon yellow", "Brownish-yellow"), whereFound = listOf("Nevada, USA", "Peru", "China", "Russia"), funFacts = listOf("Ancient artists used ground orpiment as a brilliant yellow pigment.", "It's so soft (1.5–2) you can scratch it with your fingernail.", "In sunlight, it slowly decomposes to a powdery white arsenic oxide."), uses = "Collector specimens (with caution), historical pigment, arsenic ore.", rarity = "Uncommon"),
        Specimen(id = "pentlandite", name = "Pentlandite", rockClass = RockClass.MINERAL, category = "Sulfide mineral", tagline = "Brassy bronze metallic — the world's primary nickel ore mineral.", emoji = "\uD83E\uDE9F", colorHex = 0xFFC8A050, description = "Pentlandite is a brassy bronze iron-nickel sulfide and the world's most important nickel ore mineral. It typically occurs as granular masses intergrown with pyrrhotite and chalcopyrite in magmatic sulfide deposits. Without pentlandite, our stainless steel, EV batteries, and modern alloys wouldn't exist.", formation = "Forms in magmatic sulfide deposits where nickel and iron sulfides separate from cooling mafic magma — concentrating in the lower portions of layered intrusions.", hardness = "3.5–4", luster = "Metallic", streak = "Light bronze-brown", crystalSystem = "Cubic", chemicalFormula = "(Fe,Ni)₉S₈", commonColors = listOf("Brassy bronze", "Pale bronze", "Yellowish-bronze"), whereFound = listOf("Sudbury, Ontario, Canada", "Norilsk, Russia", "Western Australia", "South Africa"), funFacts = listOf("Named after Joseph Pentland, the Irish scientist who first identified it.", "The Sudbury Basin is the site of an ancient meteorite impact — rich in pentlandite.", "Most of the world's nickel comes from pentlandite-bearing deposits."), uses = "Primary nickel ore — essential for stainless steel, batteries, and alloys.", rarity = "Common (in nickel deposits)"),
        Specimen(id = "pyrrhotite", name = "Pyrrhotite", rockClass = RockClass.MINERAL, category = "Sulfide mineral", tagline = "Bronze-brown magnetic mineral — the trickster of the sulfide world.", emoji = "\uD83E\uDE9F", colorHex = 0xFFB08050, description = "Pyrrhotite is a bronze-brown iron sulfide mineral with a distinctive metallic luster and iridescent tarnish. It is unusual among sulfides for being weakly magnetic — a property that can help identify it in the field. It is an important nickel ore when associated with pentlandite.", formation = "Forms in magmatic sulfide deposits where nickel, copper, and iron sulfides separate from cooling magma. Also found in hydrothermal veins and metamorphic rocks.", hardness = "3.5–4.5", luster = "Metallic", streak = "Dark gray-black", crystalSystem = "Monoclinic/Hexagonal", chemicalFormula = "Fe₁₋ₓS (iron-deficient)", commonColors = listOf("Bronze-brown", "Brownish-red tarnish"), whereFound = listOf("Sudbury, Ontario, Canada", "Russia", "South Africa", "Mexico"), funFacts = listOf("It's magnetic — uncommon for a sulfide mineral.", "The iridescent tarnish can show blues, purples, and reds.", "It can cause concrete deterioration when present as aggregate."), uses = "Nickel and copper ore, mineral specimen, iron sulfide reference.", rarity = "Common"),
        Specimen(id = "serpentine-antigorite", name = "Serpentine, Antigorite", rockClass = RockClass.MINERAL, category = "Silicate — Serpentine group", tagline = "Waxy green fibrous serpentine — the smooth, soapy-feeling mineral.", emoji = "\uD83D\uDFE2", colorHex = 0xFF5A8A4A, description = "Antigorite is the most common serpentine mineral — a waxy green massive silicate with a soapy feel. It forms the bulk of serpentinite rock and is the main serpentine mineral used for carving and ornamental purposes. Unlike chrysotile, it crystallizes in platy rather than fibrous form.", formation = "Forms from alteration of magnesium-rich ultramafic rocks (peridotite, dunite) in the presence of water — a process called serpentinization that occurs at mid-ocean ridges and subduction zones.", hardness = "2.5–4", luster = "Waxy to greasy", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "Mg₃Si₂O₅(OH)₄", commonColors = listOf("Green", "Yellow-green", "Dark green", "Gray-green"), whereFound = listOf("California, USA", "Italy", "New Zealand", "Canada"), funFacts = listOf("The serpentinization process produces hydrogen gas — a potential clean energy source.", "Antigorite forms platy crystals, not fibers — it's not asbestos.", "Much of California's coastal range is serpentinite."), uses = "Ornamental stone, carving, architectural cladding, industrial filler.", rarity = "Common"),
        Specimen(id = "serpentine-chrysotile", name = "Serpentine, Chrysotile", rockClass = RockClass.MINERAL, category = "Silicate — Serpentine group", tagline = "Silky white asbestos fibers — the fibrous serpentine with a complex legacy.", emoji = "\u26A0\uFE0F", colorHex = 0xFFE8E8D8, description = "Chrysotile is the fibrous variety of serpentine — commonly known as white asbestos. It forms silky, flexible fibers that can be woven into fireproof fabric. While its fire-resistant properties made it widely used historically, its health risks are now well understood. As a mineral specimen, it demonstrates nature's ability to grow flexible crystals.", formation = "Forms in veins within serpentinite where directed pressure causes antigorite to recrystallize as parallel fibers. The fibers are individually flexible — a rare property for a mineral.", hardness = "2.5–3", luster = "Silky", streak = "White", crystalSystem = "Monoclinic (fibrous)", chemicalFormula = "Mg₃Si₂O₅(OH)₄", commonColors = listOf("White", "Pale green", "Gray", "Golden"), whereFound = listOf("Quebec, Canada", "Russia", "Zimbabwe", "Arizona, USA"), funFacts = listOf("Chrysotile is the only member of the serpentine group that forms fibers.", "Ancient Persians made fireproof tablecloths from chrysotile — thrown in fire to clean.", "The name means 'gold fiber' in Greek."), uses = "Historical fireproofing, mineral specimen (with safety precautions).", rarity = "Common"),
        Specimen(id = "spinel-black", name = "Spinel, Black", rockClass = RockClass.CRYSTAL, category = "Oxide — Spinel group", tagline = "Dark opaque octahedral crystals — the iron-rich end of the spinel spectrum.", emoji = "\u2B1B", colorHex = 0xFF1A1A2A, description = "Black spinel (pleonaste or ceylonite) is an opaque, iron-rich variety of spinel that forms dark, lustrous octahedral crystals. Unlike its gemmy siblings, black spinel is common — but its sharp crystal forms and dark metallic luster make it a favorite among mineral collectors.", formation = "Iron (Fe²⁺) substitutes for magnesium in the crystal lattice, creating the dark, opaque appearance. Forms in calcium-rich metamorphic rocks like skarns and marble.", hardness = "8 (Mohs)", luster = "Sub-metallic to vitreous", streak = "Dark gray", crystalSystem = "Cubic", chemicalFormula = "(Mg,Fe)Al₂O₄", commonColors = listOf("Black", "Dark brown-black", "Dark green-black"), whereFound = listOf("New York, USA", "Sri Lanka", "Madagascar", "Italy"), funFacts = listOf("It's sometimes called 'pleonaste' — from Greek for 'abundant.'", "Black spinel is the most common spinel variety worldwide.", "Unlike black tourmaline, it forms sharp, lustrous octahedral crystals."), uses = "Collector specimens, black gemstone jewelry, accent stones.", rarity = "Common"),
        Specimen(id = "spinel-blue", name = "Spinel, Blue", rockClass = RockClass.CRYSTAL, category = "Oxide — Spinel group", tagline = "Cobalt-blue octahedrons — the rarest and most valuable spinel color.", emoji = "\uD83D\uDD35", colorHex = 0xFF2A4AAA, description = "Blue spinel, especially cobalt-blue, is the rarest and most valuable spinel color. These deep blue octahedral crystals are colored by trace cobalt and iron. The finest cobalt-blue spinels come from Vietnam and can rival fine sapphire in their depth of blue.", formation = "Blue color comes from cobalt (Co²⁺) or iron (Fe²⁺) substituting in the crystal lattice. Cobalt-bearing spinels are far rarer than iron-bearing ones.", hardness = "8 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Cubic", chemicalFormula = "MgAl₂O₄ (with Co²⁺, Fe²⁺)", commonColors = listOf("Cobalt blue", "Deep navy", "Steel blue", "Gray-blue"), whereFound = listOf("Luc Yen, Vietnam", "Sri Lanka", "Tanzania", "Madagascar"), funFacts = listOf("Cobalt-blue spinel from Vietnam can exceed $10,000 per carat.", "Cobalt spinels are the only gems colored vivid blue by cobalt alone.", "Blue spinel fluoresces bright red under UV light — a useful identification test."), uses = "Investment-grade gemstones, high-end jewelry.", rarity = "Very rare (cobalt)"),
        Specimen(id = "spinel-pink", name = "Spinel, Pink", rockClass = RockClass.CRYSTAL, category = "Oxide — Spinel group", tagline = "Bright pink octahedral crystals from the marble quarries of Myanmar.", emoji = "\uD83C\uDF38", colorHex = 0xFFF0A0B8, description = "Pink spinel from Myanmar rivals the finest pink sapphires in brilliance and color. These bright pink octahedral crystals form in the same marble deposits as Burmese rubies — and like rubies, get their color from chromium, but at a lower concentration that produces pink.", formation = "Same marble-hosted formation as Burmese ruby — chromium colors the spinel pink while the marble provides the magnesium-rich environment needed for spinel growth.", hardness = "8 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Cubic", chemicalFormula = "MgAl₂O₄ (with low Cr³⁺)", commonColors = listOf("Bright pink", "Hot pink", "Pastel pink"), whereFound = listOf("Mogok, Myanmar", "Sri Lanka", "Tajikistan"), funFacts = listOf("Burmese pink spinels are often more brilliant than pink sapphires.", "They have no pleochroism — they look the same from every angle.", "A fine pink spinel can be more valuable than a comparable pink sapphire."), uses = "Fine jewelry, engagement rings, collector gemstones.", rarity = "Rare"),
        Specimen(id = "spinel-red", name = "Spinel, Red", rockClass = RockClass.CRYSTAL, category = "Oxide — Spinel group", tagline = "The ruby impersonator — centuries of mistaken identity in crown jewels.", emoji = "\uD83D\uDC8E", colorHex = 0xFFCC1133, description = "Red spinel is nature's great gemstone imposter. For centuries, it was confused with ruby — the famous 'Black Prince's Ruby' in the British Crown Jewels is actually a 170-carat red spinel. These vivid red octahedral crystals form in marble deposits alongside true rubies. Rarity: Rare (gem quality).", formation = "Forms in magnesium-rich marble and skarn deposits where chromium is present. The bright red color comes from chromium — the same element that colors ruby — making the visual similarity unsurprising.", hardness = "8 (Mohs)", luster = "Vitreous", streak = "White", crystalSystem = "Cubic", chemicalFormula = "MgAl₂O₄ (with Cr³⁺)", commonColors = listOf("Vivid red", "Crimson", "Pinkish-red"), whereFound = listOf("Mogok, Myanmar", "Sri Lanka", "Tajikistan", "Vietnam"), funFacts = listOf("The 170-carat Black Prince's Ruby is actually a red spinel.", "Spinels form perfect octahedral crystals — the most symmetrical crystal form.", "Until 1783, no one could tell ruby and spinel apart scientifically."), uses = "High-end jewelry, collector gemstones, crown jewels.", rarity = "Rare (gem quality)"),
        Specimen(id = "tetrahedrite", name = "Tetrahedrite", rockClass = RockClass.MINERAL, category = "Sulfide — Sulfosalt mineral", tagline = "Dark metallic tetrahedral crystals — nature's copper-antimony sulfide.", emoji = "\u2B1B", colorHex = 0xFF2A2A3A, description = "Tetrahedrite is a copper-antimony sulfosalt with a distinctive dark gray-to-black metallic appearance. It forms sharp tetrahedral crystals that look like pyramids — hence its name. It's an important copper and silver ore, often containing significant silver values locked in its crystal structure.", formation = "Forms in hydrothermal veins and replacement deposits with other copper, lead, and zinc sulfides. The silver content varies by locality — some tetrahedrite is a significant silver ore.", hardness = "3.5–4", luster = "Metallic", streak = "Black to dark brown", crystalSystem = "Cubic", chemicalFormula = "Cu₁₂Sb₄S₁₃", commonColors = listOf("Dark gray", "Black", "Steel gray"), whereFound = listOf("Peru", "Germany", "Romania", "Colorado, USA"), funFacts = listOf("Some tetrahedrite contains up to 30% silver by weight.", "It forms perfect tetrahedron-shaped crystals — four triangular faces.", "It's in a solid solution series with tennantite (arsenic-rich version)."), uses = "Copper and silver ore, collector specimens.", rarity = "Common"),
        Specimen(id = "turquoise-kingman", name = "Turquoise, Kingman Mine", rockClass = RockClass.MINERAL, category = "Phosphate — Turquoise variety", tagline = "Classic Arizona sky-blue turquoise with light brown matrix webbing.", emoji = "\uD83D\uDD35", colorHex = 0xFF5A9ACA, description = "Kingman turquoise from Arizona's Kingman Mine is the most recognizable American turquoise — bright sky-blue with a distinctive light brown to black matrix that forms a spiderweb pattern. The Kingman Mine has produced turquoise for over 1,000 years, originally by Ancestral Puebloan peoples.", formation = "Forms when copper-rich groundwater percolates through aluminum-rich volcanic rocks. The blue color comes from copper, the green from iron or zinc substituting in the crystal structure.", hardness = "5–6", luster = "Waxy to sub-vitreous", streak = "White to pale blue", crystalSystem = "Triclinic", chemicalFormula = "CuAl₆(PO₄)₄(OH)₈·4H₂O", commonColors = listOf("Sky blue", "Robin's egg blue", "Blue with brown matrix"), whereFound = listOf("Kingman, Arizona, USA", "Mohave County, Arizona"), funFacts = listOf("The Kingman Mine is one of the oldest continuously operated mines in the US.", "Native Americans mined Kingman turquoise at least 1,000 years ago.", "It's stabilized for jewelry — natural Kingman turquoise is quite porous."), uses = "Jewelry, cabochons, Native American silverwork, beads, inlay.", rarity = "Uncommon"),
        Specimen(id = "turquoise-persian", name = "Turquoise, Persian", rockClass = RockClass.MINERAL, category = "Phosphate — Turquoise variety", tagline = "Intense robin's-egg blue — the world's most prized turquoise from Iran.", emoji = "\uD83D\uDC99", colorHex = 0xFF4A9AE0, description = "Persian turquoise from Iran is arguably the finest turquoise in the world — an intense, pure robin's-egg blue with minimal matrix. Mined for over 5,000 years, Persian turquoise has decorated the domes of mosques, the hilts of swords, and the crowns of shahs. Its color is universally regarded as the ideal. Rarity: Rare (high quality).", formation = "Forms in copper-rich trachyte and andesite volcanic rocks. The intense blue with minimal matrix comes from high copper and low iron-zinc content in the groundwater that formed it.", hardness = "5–6", luster = "Waxy to sub-vitreous", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "CuAl₆(PO₄)₄(OH)₈·4H₂O", commonColors = listOf("Intense robin's-egg blue", "Pure sky blue", "Uniform medium blue"), whereFound = listOf("Nishapur, Khorasan Province, Iran", "Kerman, Iran"), funFacts = listOf("Persian turquoise has been mined for over 5,000 years.", "The domes of Isfahan's mosques are tiled with Persian turquoise.", "It's the only turquoise that doesn't typically need stabilization."), uses = "High-end jewelry, inlay, domed cabochons, collector specimens.", rarity = "Rare (high quality)"),
    )
}
